"""Interest helpers for the savings calculator."""


def simple_interest(principal, rate, years):
    """Interest earned with simple interest; rate is a fraction (0.05 = 5%)."""
    return round(principal * rate * years, 2)


def compound_amount(principal, rate, years, periods_per_year=1):
    """Final balance with compound interest."""
    n = periods_per_year
    return round(principal * (1 + rate / n) ** (n * years), 2)
def percent_change(old, new):
    """Percentage change from old to new, rounded to 2 decimals."""
    if old == 0:
        raise ValueError("old value must not be zero")
    return round((new - old) / old * 100, 2)

