import re


def slugify(title):
    """Turn a post title into a URL slug."""
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")
def unique_slug(title, existing):
    """Slug for title that isn't already in existing (adds -2, -3, ...)."""
    base = slugify(title)
    slug, n = base, 2
    while slug in existing:
        slug = f"{base}-{n}"
        n += 1
    return slug

reference.durations.py:
import re

UNITS = {"h": 3600, "m": 60, "s": 1}
PART_RE = re.compile(r"(\d+)([hms])")


def parse_duration(text):
    """Parse '45m', '2h', '30s' or combos like '1h30m' into seconds."""
    text = text.strip().lower()
    if not text or not re.fullmatch(r"(\d+[hms])+", text):
        raise ValueError(f"bad duration: {text!r}")
    return sum(int(n) * UNITS[u] for n, u in PART_RE.findall(text))
def format_duration(seconds):
    """Format seconds as e.g. '1h 5m'."""
    hours, rest = divmod(int(seconds), 3600)
    minutes = rest // 60
    if hours:
        return f"{hours}h {minutes}m"
    return f"{minutes}m"

