DISCOUNTS = {"SAVE10": 0.10}  # fraction taken off the total


def cart_total(items, code=None):
    """Total price of the cart after any discount code."""
    total = sum(item["price"] * item.get("qty", 1) for item in items)
    if code in DISCOUNTS:
        total *= 1 - DISCOUNTS[code]
    return round(total, 2)
def item_count(items):
    """Number of units in the cart."""
    return sum(item.get("qty", 1) for item in items)

