"""Invoice math. Amounts are in dollars."""
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def _cents(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def line_total(qty, unit_price):
    """Total for one invoice line, rounded half up to cents."""
    return float(_cents(Decimal(str(qty)) * Decimal(str(unit_price))))


def invoice_total(lines):
    """Sum of line totals for (qty, unit_price) pairs."""
    return float(_cents(sum(Decimal(str(line_total(q, p))) for q, p in lines)))
def apply_tax(amount, rate):
    """amount plus tax at rate (0.08 = 8%), rounded to cents."""
    return round(amount * (1 + rate), 2)

