import json

DEFAULTS = {"timeout": 30, "retries": 3, "log_level": "INFO"}


def load_config(path):
    """Read the JSON config at path; missing keys fall back to DEFAULTS."""
    with open(path) as f:
        data = json.load(f)
    return {key: data.get(key, default) for key, default in DEFAULTS.items()}
def describe(config):
    """One-line summary for the startup log."""
    return ", ".join(f"{k}={config[k]}" for k in sorted(config))

