"""Builds the plain-text monthly report."""


def format_amount(value):
    """Format a dollar amount: 1,234.50, negatives as (1,234.50)."""
    text = f"{abs(value):,.2f}"
    return f"({text})" if value < 0 else text
def report_lines(rows):
    """rows is a list of (label, amount) pairs."""
    width = max((len(label) for label, _ in rows), default=0)
    return [f"{label.ljust(width)}  {format_amount(amount)}" for label, amount in rows]


def total(rows):
    return sum(amount for _, amount in rows)

