"""Retry wrapper around the inventory API client."""
import time


class HTTPError(Exception):
    def __init__(self, status):
        super().__init__(f"HTTP {status}")
        self.status = status


def fetch_with_retry(fetch, attempts=3, delay=1, sleep=time.sleep):
    """Call fetch(), retrying 5xx errors with a doubling wait; 4xx raise at once."""
    wait = delay
    for attempt in range(attempts):
        try:
            return fetch()
        except HTTPError as err:
            if err.status < 500 or attempt == attempts - 1:
                raise
            sleep(wait)
            wait *= 2

