"""Feature flags. rollout is the percent of user buckets (0-99) that get it."""

FLAGS = {
    "beta_reports": {"enabled": True, "rollout": 20, "added": "2025-01-15"},
    "fast_sync": {"enabled": False, "rollout": 0, "added": "2026-09-30"},
    "ai_summary": {"enabled": True, "rollout": 5, "added": "2026-10-20"},
}
def is_enabled(name, bucket):
    """True if flag name is on for this user bucket (0-99)."""
    flag = FLAGS.get(name)
    if flag is None or not flag["enabled"]:
        return False
    return bucket < flag["rollout"]

