"""Exchange rates from USD, kept by hand from finance's sheet."""

RATES_UPDATED = "2026-11-15"

RATES = {
    "EUR": 0.94,
    "GBP": 0.78,
    "JPY": 149.5,
    "CAD": 1.39,
    "MXN": 18.2,
}
def convert(amount_usd, currency):
    """Convert a USD amount into currency, rounded to 2 decimals."""
    if currency == "USD":
        return amount_usd
    if currency not in RATES:
        raise KeyError(f"no rate for {currency}")
    return round(amount_usd * RATES[currency], 2)

